    def has_single_arg(func):
        """Check if function has exactly one positional argument."""
        spec = inspect.signature(func)
        if len(spec.parameters) != 1:
            return False
        arg = next(iter(spec.parameters.values()))
        return arg.kind not in (arg.VAR_POSITIONAL, arg.VAR_KEYWORD)

    def has_1pos_and_kwonly(func):
        """Check if function has exactly one positional arg and potentially keyword-only args."""
        spec = inspect.signature(func)
        params = list(spec.parameters.values())
        if not params:
            return False
        # First parameter must be positional
        if params[0].kind not in (inspect.Parameter.POSITIONAL_ONLY, inspect.Parameter.POSITIONAL_OR_KEYWORD):
            return False
        # Rest must be keyword-only or VAR_KEYWORD
        for p in params[1:]:
            if p.kind not in (inspect.Parameter.KEYWORD_ONLY, inspect.Parameter.VAR_KEYWORD):
                return False
        return True


